import * as THREE from "three";
import ranks from "./blueNoise32.bin?arraybuffer&base64";

/** Fixed, tileable blue noise generated by scripts/generate-blue-noise.js. */
export function createBlueNoiseTexture() {
  // Three's WebGPU backend supports R32UI; keep the embedded ranks at 16 bits.
  const texture = new THREE.DataTexture(
    Uint32Array.from(new Uint16Array(ranks)),
    32,
    32,
    THREE.RedIntegerFormat,
    THREE.UnsignedIntType,
  );
  texture.name = "GaussianSplatBlueNoise";
  texture.needsUpdate = true;
  return texture;
}
